@Composable
fun BattleScreen(
    player: Hero,
    enemigos: List<Enemy>,
    chapter: StoryChapter,
    playerHp: Int,
    playerXP: Int,
    playerNextLevelXP: Int,
    playerLevel: Int,
    playerAttackIds: List<Int>,
    enemyHpMap: Map<Int, Int>,
    battleMessage: String,
    battleFinished: Boolean,
    isPlayerTurn: Boolean,
    isResolvingTurn: Boolean,
    requiresSkillSelection: Boolean,
    pendingSkillChoices: List<AttackMove>,
    playerWon: Boolean,
    isLastChapter: Boolean,
    showContinueStoryAction: Boolean = true,
    soundCue: BattleSoundCue?,
    onSoundConsumed: () -> Unit,
    onAttack: (AttackMove, List<Int>) -> Unit,
    onSelectSkill: (Int) -> Unit,
    onContinueStory: () -> Unit,
    onExit: () -> Unit,
    onRetry: () -> Unit
) {
    val playerAttacks = remember(playerAttackIds) { getAttacksByIds(*playerAttackIds.toIntArray()) }
    val selectedEnemyIds = remember { mutableStateListOf<Int>() }
    var selectedAttack by remember { mutableStateOf<AttackMove?>(null) }
    var showExitConfirmation by remember { mutableStateOf(false) }
    val playSoundCue = rememberAttackSoundPlayer()
    val aliveEnemies = enemigos.filter { (enemyHpMap[it.id] ?: 0) > 0 }
    val aliveEnemyIds = aliveEnemies.map { it.id }.toSet()

    BackHandler {
        showExitConfirmation = true
    }

    val animatedPlayerHp by animateIntAsState(
        targetValue = playerHp,
        animationSpec = tween(durationMillis = 650),
        label = "playerHpAnimation"
    )

    LaunchedEffect(soundCue) {
        val cue = soundCue ?: return@LaunchedEffect
        playSoundCue(cue)
        onSoundConsumed()
    }

    LaunchedEffect(aliveEnemyIds) {
        selectedEnemyIds.removeAll { it !in aliveEnemyIds }
    }

    LaunchedEffect(isPlayerTurn, battleFinished, requiresSkillSelection) {
        if (!isPlayerTurn || battleFinished || requiresSkillSelection) {
            selectedAttack = null
            selectedEnemyIds.clear()
        }
    }

    if (showExitConfirmation) {
        AlertDialog(
            onDismissRequest = { showExitConfirmation = false },
            title = { Text("Salir del combate") },
            text = { Text("Si sales ahora, se perderá el progreso de este combate. ¿Seguro que deseas salir?") },
            confirmButton = {
                Button(onClick = {
                    showExitConfirmation = false
                    onExit()
                }) {
                    Text("Sí, salir")
                }
            },
            dismissButton = {
                TextButton(onClick = { showExitConfirmation = false }) {
                    Text("Cancelar")
                }
            }
        )
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(18.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        item {
            Text("Combate por turnos", style = MaterialTheme.typography.headlineMedium,
                fontWeight = FontWeight.Bold, color = Color(0xFF3A8CA3))
            Text(chapter.title, color = Color(0xFF5F5F7A))
        }

        item {
            val heroRows = buildFormationRows(listOf(player))
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                heroRows.forEach { rowHeroes ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp, Alignment.CenterHorizontally)
                    ) {
                        rowHeroes.forEach { hero ->
                            val slotModifier = when {
                                rowHeroes.size == 1 && heroRows.size > 1 -> Modifier.fillMaxWidth(0.48f)
                                rowHeroes.size == 1 -> Modifier.fillMaxWidth()
                                else -> Modifier.weight(1f)
                            }

                            FighterCardHero(
                                title = "Tu personaje",
                                character = hero,
                                currentHp = animatedPlayerHp,
                                currentXP = playerXP,
                                nextLevelXP = playerNextLevelXP,
                                barColor = Color(0xFF0BA896),
                                modifier = slotModifier
                            )
                        }
                    }
                }
            }
        }

        item {
            val enemyRows = buildFormationRows(aliveEnemies)
            Column(
                modifier = Modifier.animateContentSize(animationSpec = tween(durationMillis = 350)),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                enemyRows.forEach { rowEnemies ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp, Alignment.CenterHorizontally)
                    ) {
                        rowEnemies.forEach { enemy ->
                            val hp = enemyHpMap[enemy.id] ?: 0
                            val animatedEnemyHp by animateIntAsState(
                                targetValue = hp,
                                animationSpec = tween(durationMillis = 650),
                                label = "enemyHpAnimation_${enemy.id}"
                            )
                            val slotModifier = when {
                                rowEnemies.size == 1 && enemyRows.size > 1 -> Modifier.fillMaxWidth(0.48f)
                                rowEnemies.size == 1 -> Modifier.fillMaxWidth()
                                else -> Modifier.weight(1f)
                            }

                            Box(
                                modifier = slotModifier
                                    .border(
                                        width = if (enemy.id in selectedEnemyIds) 3.dp else 1.dp,
                                        color = if (enemy.id in selectedEnemyIds) Color(0xFF3A0CA3) else Color.LightGray,
                                        shape = RoundedCornerShape(18.dp)
                                    )
                                    .clickable(enabled = !isResolvingTurn) {
                                        val attack = selectedAttack ?: return@clickable
                                        if (!attack.necesitaObjetivo()) return@clickable
                                        val maxTargets = attack.maxTargets()

                                        if (enemy.id in selectedEnemyIds) {
                                            selectedEnemyIds.remove(enemy.id)
                                        } else if (selectedEnemyIds.size < maxTargets) {
                                            selectedEnemyIds.add(enemy.id)
                                        }

                                        val resolved = resolveAttackTargetIds(
                                            attack = attack,
                                            selectedEnemyIds = selectedEnemyIds,
                                            aliveEnemyIds = aliveEnemyIds
                                        ) ?: return@clickable

                                        if (resolved.size >= maxTargets) {
                                            onAttack(attack, resolved)
                                            selectedAttack = null
                                            selectedEnemyIds.clear()
                                        }
                                    }
                            ) {
                                FighterCardEnemy(
                                    title = enemy.name,
                                    character = enemy,
                                    currentHp = animatedEnemyHp,
                                    barColor = Color(0xFFE63946),
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }
                        }
                    }
                }
            }
        }

        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)
            ) {
                Text(battleMessage, modifier = Modifier.padding(16.dp),
                    style = MaterialTheme.typography.bodyLarge)
            }
        }

        if (requiresSkillSelection) {
            item {
                Text("Elige una nueva habilidad", fontWeight = FontWeight.Bold, color = Color(0xFF3A8CA3))
            }

            items(pendingSkillChoices) { skill ->
                OutlinedButton(
                    onClick = { onSelectSkill(skill.id) },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(18.dp)
                ) {
                    Text("Aprender ${skill.name}")
                }
            }
        }

        // Barra de ataque con iconos (max 4)
        if (!battleFinished && isPlayerTurn && !requiresSkillSelection) {
            item {
                AttackCommandBar(
                    attacks = playerAttacks,
                    canUseAttacks = !isResolvingTurn,
                    selectedAttack = selectedAttack,
                    selectedTargetsCount = selectedEnemyIds.size,
                    onAttackClick = { attack ->
                        selectedAttack = attack
                        selectedEnemyIds.clear()

                        if (!attack.necesitaObjetivo()) {
                            onAttack(attack, emptyList())
                            selectedAttack = null
                            return@AttackCommandBar
                        }
                    }
                )
            }
        } else if (battleFinished && !requiresSkillSelection) {
            item {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    if (playerWon) {
                        if (showContinueStoryAction && isLastChapter) {
                            Button(
                                onClick = onExit,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(18.dp)
                            ) {
                                Text("  Volver al menú principal")
                            }
                        } else if (showContinueStoryAction) {
                            Button(
                                onClick = onContinueStory,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(18.dp)
                            ) {
                                Text("▶  Continuar historia")
                            }
                        }
                    }
                    OutlinedButton(
                        onClick = onRetry,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp)
                    ) {
                        Text(if (playerWon) "Volver a jugar" else "Intentar otra vez")
                    }
                    if (!showContinueStoryAction || !isLastChapter || !playerWon) {
                        OutlinedButton(
                            onClick = onExit,
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(18.dp)
                        ) {
                            Text("Volver a partidas")
                        }
                    }
                }
            }
        }
    }
}

private fun <T> buildFormationRows(items: List<T>): List<List<T>> {
    return when (items.size) {
        0 -> emptyList()
        1 -> listOf(items)
        2 -> listOf(items)
        3 -> listOf(listOf(items[0]), listOf(items[1], items[2]))
        4 -> listOf(items.take(2), items.drop(2))
        else -> items.chunked(2)
    }
}

